import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { MDBContainer, MDBCard, MDBCardBody, MDBTable, MDBTableHead, MDBTableBody, MDBBtn } from 'mdb-react-ui-kit';

const AgencyDashboard: React.FC = () => {
    const navigate = useNavigate();
    const [jobSeekers, setJobSeekers] = useState<any[]>([]);
    const [agencyName, setAgencyName] = useState<any>(null);

    useEffect(() => {
        const token = localStorage.getItem('token');
        const storedUser = localStorage.getItem('user');

        if (!token || !storedUser) {
            navigate('/login');
            return;
        }

        const user = JSON.parse(storedUser);
        setAgencyName(user.firstName);

        // Getting all the job seekers associated with that particular agency
        axios.get(`http://localhost:8080/app/jobSeekers/${user.id}`, {
            headers: { Authorization: `Bearer ${token}` },
        })
            .then(response => setJobSeekers(response.data))
            .catch(error => console.error('Error fetching job seekers:', error));
    }, [navigate]);

    const updateStatus = async (userId: number, status: string) => {
        const token = localStorage.getItem('token');
        try {
            const response = await fetch('http://localhost:8080/app/updateJobSeekerStatus', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    Authorization: `Bearer ${token}`,
                },
                body: JSON.stringify({ userId, status }),
            });

            if (!response.ok) {
                throw new Error('Failed to update status');
            }

            setJobSeekers((prev) =>
                prev.map((seeker) =>
                    seeker.id === userId ? { ...seeker, status } : seeker
                )
            );
        } catch (error) {
            console.error('Error updating status:', error);
        }
    };

    const handleChat = (userId: number, agencyId: number) => {
        navigate(`/chat/${userId}/${agencyId}`);      
    };

    return (

        <MDBContainer className="mt-5">
            <nav className="navbar bg-primary-gradient col-lg-12 col-12 p-0 fixed-top navbar-inverse d-flex flex-row">

     <div className="bg-white text-center navbar-brand-wrapper">
          <a className="navbar-brand brand-logo" href="#"><img src="../images/logo_star_black.png" /></a>
          <a className="navbar-brand brand-logo-mini" href="#"><img src="../images/logo_star_mini.jpg" alt=""/></a>
     </div>

     <div className="navbar-menu-wrapper d-flex align-items-center">
          <button className="navbar-toggler navbar-toggler hidden-md-down align-self-center mr-3" type="button" data-toggle="minimize">
                  <span className="navbar-toggler-icon"></span>
          </button>

          <ul className="navbar-nav ml-lg-auto d-flex align-items-center flex-row">
              <li className="nav-item">
                  <a className="nav-link" href="#"><i className="fa fa-refresh"></i></a>
              </li>
              </ul>

          <button className="navbar-toggler navbar-toggler-right hidden-lg-up align-self-center" type="button" data-toggle="offcanvas">
               <span className="navbar-toggler-icon"></span>
          </button>
     </div>
</nav>
            <h1 className="text-center">{agencyName}</h1>
            <MDBCard className="p-4 mt-3">
                <MDBCardBody>
                    <h2>Associated Job Seekers</h2>
                    {jobSeekers.length === 0 ? (
                        <p>No job seekers associated with your agency.</p>
                    ) : (
                        <MDBTable striped>
                            <MDBTableHead>
                                <tr>
                                    <th>First Name</th>
                                    <th>Last Name</th>
                                    <th>Email</th>
                                    <th>Phone</th>
                                    <th>Gender</th>
                                    <th>Hobbies</th>
                                    <th>Profile Image</th>
                                    <th>Resume</th>
                                    <th>Status</th>
                                    <th>Actions</th>
                                </tr>
                            </MDBTableHead>
                            <MDBTableBody>
                                {jobSeekers.map((jobSeeker) => (
                                    <tr key={jobSeeker.id}>
                                        <td>{jobSeeker.firstName}</td>
                                        <td>{jobSeeker.lastName}</td>
                                        <td>{jobSeeker.email}</td>
                                        <td>{jobSeeker.phone}</td>
                                        <td>{jobSeeker.gender}</td>
                                        <td>
                                            {Array.isArray(jobSeeker.hobbies) ? jobSeeker.hobbies.join(', ') : 'No hobbies listed'}
                                        </td>
                                        <td>
                                            <img 
                                                src={jobSeeker.profileImage} 
                                                alt={`${jobSeeker.firstName}'s Profile`} 
                                                style={{ width: '50px', height: '50px', borderRadius: '50%' }} 
                                            />
                                        </td>
                                        <td>
                                            {jobSeeker.resume ? (
                                                <a href={jobSeeker.resume} target="_blank" rel="noopener noreferrer">View Resume</a>
                                            ) : 'No resume uploaded'}
                                        </td>
                                        <td>{jobSeeker.status}</td>
                                        <td>
                                            {jobSeeker.status === 'pending' && (
                                                <>
                                                    <MDBBtn 
                                                        onClick={() => updateStatus(jobSeeker.id, 'confirmed')}
                                                        color="success" 
                                                        size="sm"
                                                    >
                                                        Confirm
                                                    </MDBBtn>
                                                    <MDBBtn 
                                                        onClick={() => updateStatus(jobSeeker.id, 'declined')}
                                                        color="danger" 
                                                        size="sm"
                                                    >
                                                        Decline
                                                    </MDBBtn>
                                                </>
                                            )}
                                            {jobSeeker.status === 'confirmed' && (
                                                <MDBBtn 
                                                    onClick={() => handleChat(jobSeeker.id, jobSeeker.agencyId)}
                                                    color="info" 
                                                    size="sm"
                                                >
                                                    Chat
                                                </MDBBtn>
                                            )}
                                        </td>
                                    </tr>
                                ))}
                            </MDBTableBody>
                        </MDBTable>
                    )}
                </MDBCardBody>
            </MDBCard>
        </MDBContainer>
    );
};

export default AgencyDashboard;
